=== DIFF A ===
diff --git a/lib/matching/__tests__/write-paths-parity.test.ts b/lib/matching/__tests__/write-paths-parity.test.ts
new file mode 100644
index 00000000..ec4dbb0c
--- /dev/null
+++ b/lib/matching/__tests__/write-paths-parity.test.ts
@@ -0,0 +1,231 @@
+/**
+ * Parity test (B.2) — computeAndPersistMatches (background precompute) and
+ * persistSessionMatches (detail-page path) must write identical values for the
+ * 21 computed columns when given the same cargo×vessel pair.
+ *
+ * Both writers call computeStoredMatchEconomics with the same inputs, so
+ * tce_usd_per_day and all downstream economics fields are deterministic.
+ * The test runs both paths against the SAME in-memory DB (different session IDs
+ * so the UNIQUE constraint doesn't collide) and compares the resulting rows.
+ *
+ * The worksheet laycanStart is seeded from parseLaycan(cargo.laycan) so the
+ * fail-closed rebuild in persistSessionMatches does NOT fire — both paths store
+ * the same worksheet.readiness.verdict.
+ */
+import Database from 'better-sqlite3';
+import { runMigrations } from '@/lib/migrations/runner';
+import { allMigrations } from '@/lib/migrations';
+import { computeAndPersistMatches } from '@/lib/matching/compute-matches';
+import { persistSessionMatches } from '@/lib/matching/persist-session-matches';
+import { listMatches } from '@/lib/matching/matches-repository';
+import { resolveSyntheticCargo, resolveSyntheticVessel } from '@/lib/sample-data/synthetic-economics';
+import { parseLaycan } from '@/lib/sailing/date-parsing';
+import type { Match, FitBreakdown, MatchWorksheet, MatchHardFilters } from '@/lib/types';
+
+jest.mock('@/lib/matching/pair-analyzer', () => ({
+  analyzePairs: jest.fn(),
+}));
+
+import { analyzePairs } from '@/lib/matching/pair-analyzer';
+
+function freshDb(): Database.Database {
+  const db = new Database(':memory:');
+  runMigrations(db, allMigrations);
+  return db;
+}
+
+const SAMPLE_FIT_BREAKDOWN: FitBreakdown = {
+  components: [
+    { factor: 'utilisation', label: 'Size / utilisation', weight: 25, score: 22, rationale: '88%' },
+    { factor: 'timing',      label: 'Timing',             weight: 20, score: 18, rationale: 'ideal' },
+    { factor: 'ballast',     label: 'Ballast distance',   weight: 20, score: 14, rationale: '320nm' },
+    { factor: 'classFit',    label: 'Class fit',          weight: 12, score: 10, rationale: 'supramax' },
+    { factor: 'cargoType',   label: 'Cargo type',         weight:  8, score:  7, rationale: 'grain' },
+    { factor: 'cranes',      label: 'Cranes',             weight:  8, score:  6, rationale: 'geared' },
+    { factor: 'volume',      label: 'Volume / stowage',   weight:  4, score:  3, rationale: 'ok' },
+    { factor: 'draft',       label: 'Draft',              weight:  3, score:  2, rationale: 'fits' },
+  ],
+  totalWeight: 100,
+  fitPercent: 82,
+  partCargo: false,
+  vesselClass: 'supramax',
+  sanctionsPenalty: 0,
+  appliedCap: null,
+  inputs: {
+    distanceNm: 320,
+    gapDays: 3,
+    verdict: 'ideal',
+    utilisation: 0.88,
+    vesselDwt: 57000,
+    cargoWtMax: 50000,
+  },
+};
+
+const HARD_FILTERS: MatchHardFilters = {
+  draft: { pass: true },
+  crane: { pass: true },
+  volume: { pass: true },
+  cargoVessel: { pass: true },
+  destDraft: { pass: true },
+  destCrane: { pass: true },
+  cargoWeight: { pass: true },
+};
+
+describe('write-paths-parity (B.2) — computeAndPersistMatches vs persistSessionMatches', () => {
+  const now = new Date();
+  const demoCargo = resolveSyntheticCargo(now);
+  const demoVessel = resolveSyntheticVessel(now);
+
+  // Use the actual cargo laycan so the fail-closed rebuild in persistSessionMatches
+  // does not fire (storedLaycanStart === freshLaycanStart).
+  const parsedLaycan = parseLaycan(demoCargo.laycan)!;
+  const laycanStartIso = parsedLaycan.start.toISOString().slice(0, 10);
+  const laycanEndIso   = parsedLaycan.end.toISOString().slice(0, 10);
+
+  const worksheet: MatchWorksheet = {
+    readiness: {
+      verdict: 'ideal',
+      explanation: 'on-window',
+      openPosition: null,
+      openDate: new Date(now.getTime() + 3 * 86_400_000).toISOString().slice(0, 10),
+      laycanStart: laycanStartIso,
+      laycanEnd:   laycanEndIso,
+      distanceNm: 320,
+      distanceExact: true,
+      speedKn: 13,
+      sailingDays: 1,
+      arrivalDate: new Date(now.getTime() + 4 * 86_400_000).toISOString().slice(0, 10),
+      gapDays: 8,
+    },
+    vessel: {
+      dwtSummer: 58000,
+      draftMax: 12.5,
+      grainCapacity: null,
+      grainCapacityUnit: null,
+      geared: true,
+      vesselType: 'BULK_CARRIER',
+      flag: 'Marshall Islands',
+      built: 2015,
+      pandi: 'Gard',
+      classSociety: 'DNV',
+      lastCargoes: null,
+      dwcc: 55500,
+    },
+    cargo: {
+      weightMt: 50000,
+      weightMtEffective: 50000,
+      cargoType: 'BULK',
+      loadPort: 'CNSHA',
+      dischargePort: 'NLRTM',
+    },
+    hardFilters: HARD_FILTERS,
+  };
+
+  const match: Match = {
+    cargoEmailId: demoCargo.emailId,
+    cargoItemIndex: 1,
+    vesselEmailId: demoVessel.emailId,
+    vesselItemIndex: 2,
+    score: 89,
+    matchLevel: 'good',
+    matchReasons: ['Good DWT fit — 58,000 mt vessel vs 50,000 mt grain cargo'],
+    issues: [],
+    fitPercent: 82,
+    fitBreakdown: SAMPLE_FIT_BREAKDOWN,
+    worksheet,
+    hardFilters: HARD_FILTERS,
+    scoreBreakdown: {
+      components: [{ label: 'Geographic proximity', points: 16, max: 20 }],
+      basePhysical: 60,
+      readinessAdjustment: 20,
+      sanctionsAdjustment: 0,
+      finalScore: 80,
+    },
+  };
+
+  let computeRow: ReturnType<typeof listMatches>[number];
+  let persistRow: ReturnType<typeof listMatches>[number];
+
+  beforeAll(async () => {
+    const db = freshDb();
+
+    // Background precompute path
+    (analyzePairs as jest.Mock).mockResolvedValueOnce({
+      matches: [match],
+      lowConfidenceMatches: [],
+      insufficientData: [],
+      blockedMatches: [],
+    });
+    await computeAndPersistMatches([demoCargo], [demoVessel], 'session-compute', db);
+
+    // Detail-page path (different session so UNIQUE constraint doesn't collide)
+    persistSessionMatches(db, 'session-persist', [match], [demoCargo], [demoVessel]);
+
+    const rows = listMatches(db, { sortBy: 'score', sortDir: 'desc' });
+    computeRow = rows.find((r) => r.user_id === 'session-compute')!;
+    persistRow  = rows.find((r) => r.user_id === 'session-persist')!;
+  });
+
+  it('both rows are written', () => {
+    expect(computeRow).toBeDefined();
+    expect(persistRow).toBeDefined();
+  });
+
+  // ── columns 1–6: route / timing ───────────────────────────────────────────
+  it('cargo_type matches',      () => expect(computeRow.cargo_type).toBe(persistRow.cargo_type));
+  it('load_port matches',       () => expect(computeRow.load_port).toBe(persistRow.load_port));
+  it('discharge_port matches',  () => expect(computeRow.discharge_port).toBe(persistRow.discharge_port));
+  it('laycan_start matches',    () => expect(computeRow.laycan_start).toBe(persistRow.laycan_start));
+  it('laycan_end matches',      () => expect(computeRow.laycan_end).toBe(persistRow.laycan_end));
+  it('vessel_dwt matches',      () => expect(computeRow.vessel_dwt).toBe(persistRow.vessel_dwt));
+
+  // ── columns 7–10: economics ───────────────────────────────────────────────
+  it('tce_usd_per_day matches',         () => expect(computeRow.tce_usd_per_day).toBe(persistRow.tce_usd_per_day));
+  it('distance_nm matches',             () => expect(computeRow.distance_nm).toBe(persistRow.distance_nm));
+  it('freight_rate_usd_per_mt matches', () => expect(computeRow.freight_rate_usd_per_mt).toBe(persistRow.freight_rate_usd_per_mt));
+  it('freight_rate_source matches',     () => expect(computeRow.freight_rate_source).toBe(persistRow.freight_rate_source));
+
+  // ── columns 11–12: identity ───────────────────────────────────────────────
+  it('vessel_name matches', () => expect(computeRow.vessel_name).toBe(persistRow.vessel_name));
+  it('cargo_ref matches',   () => expect(computeRow.cargo_ref).toBe(persistRow.cargo_ref));
+
+  // ── columns 13–14: fit ────────────────────────────────────────────────────
+  it('fit_percent is non-null and matches', () => {
+    expect(computeRow.fit_percent).not.toBeNull();
+    expect(computeRow.fit_percent).toBeCloseTo(persistRow.fit_percent!);
+  });
+  it('fit_breakdown component count matches', () => {
+    expect(computeRow.fit_breakdown).not.toBeNull();
+    const c = JSON.parse(computeRow.fit_breakdown!);
+    const p = JSON.parse(persistRow.fit_breakdown!);
+    expect(c.components).toHaveLength(p.components.length);
+  });
+
+  // ── columns 15–16: item indices ───────────────────────────────────────────
+  it('cargo_item_index matches',  () => expect(computeRow.cargo_item_index).toBe(persistRow.cargo_item_index));
+  it('vessel_item_index matches', () => expect(computeRow.vessel_item_index).toBe(persistRow.vessel_item_index));
+
+  // ── column 17: worksheet ─────────────────────────────────────────────────
+  it('worksheet_json readiness.verdict matches', () => {
+    expect(computeRow.worksheet_json).not.toBeNull();
+    const cw = JSON.parse(computeRow.worksheet_json!);
+    const pw = JSON.parse(persistRow.worksheet_json!);
+    expect(cw.readiness.verdict).toBe(pw.readiness.verdict);
+  });
+
+  // ── columns 18–19: consumption / ballast ─────────────────────────────────
+  it('consumption_estimated matches', () => expect(computeRow.consumption_estimated).toBe(persistRow.consumption_estimated));
+  it('ballast_distance_nm matches',   () => expect(computeRow.ballast_distance_nm).toBe(persistRow.ballast_distance_nm));
+
+  // ── column 20: breakeven ─────────────────────────────────────────────────
+  it('breakeven_tce_usd_per_day is non-null and matches', () => {
+    expect(computeRow.breakeven_tce_usd_per_day).not.toBeNull();
+    expect(computeRow.breakeven_tce_usd_per_day).toBe(persistRow.breakeven_tce_usd_per_day);
+  });
+
+  // ── column 21: reason_structured ─────────────────────────────────────────
+  it('reason_structured matches', () => {
+    // Both paths write m.scoreBreakdown as JSON (or null when absent)
+    expect(computeRow.reason_structured).toBe(persistRow.reason_structured);
+  });
+});
