@@ -0,0 +1,231 @@
+/**
+ * Parity test (B.2) — computeAndPersistMatches (background precompute) and
+ * persistSessionMatches (detail-page path) must write identical values for the
+ * 21 computed columns when given the same cargo×vessel pair.
+ *
+ * Both writers call computeStoredMatchEconomics with the same inputs, so
+ * tce_usd_per_day and all downstream economics fields are deterministic.
+ * The test runs both paths against the SAME in-memory DB (different session IDs
+ * so the UNIQUE constraint doesn't collide) and compares the resulting rows.
+ *
+ * The worksheet laycanStart is seeded from parseLaycan(cargo.laycan) so the
+ * fail-closed rebuild in persistSessionMatches does NOT fire — both paths store
+ * the same worksheet.readiness.verdict.
+ */
+import Database from 'better-sqlite3';
+import { runMigrations } from '@/lib/migrations/runner';
+import { allMigrations } from '@/lib/migrations';
+import { computeAndPersistMatches } from '@/lib/matching/compute-matches';
+import { persistSessionMatches } from '@/lib/matching/persist-session-matches';
+import { listMatches } from '@/lib/matching/matches-repository';
+import { resolveSyntheticCargo, resolveSyntheticVessel } from '@/lib/sample-data/synthetic-economics';
+import { parseLaycan } from '@/lib/sailing/date-parsing';
+import type { Match, FitBreakdown, MatchWorksheet, MatchHardFilters } from '@/lib/types';
+
+jest.mock('@/lib/matching/pair-analyzer', () => ({
+  analyzePairs: jest.fn(),
+}));
+
+import { analyzePairs } from '@/lib/matching/pair-analyzer';
+
+function freshDb(): Database.Database {
+  const db = new Database(':memory:');
+  runMigrations(db, allMigrations);
+  return db;
+}
+
+const SAMPLE_FIT_BREAKDOWN: FitBreakdown = {
+  components: [
+    { factor: 'utilisation', label: 'Size / utilisation', weight: 25, score: 22, rationale: '88%' },
+    { factor: 'timing',      label: 'Timing',             weight: 20, score: 18, rationale: 'ideal' },
+    { factor: 'ballast',     label: 'Ballast distance',   weight: 20, score: 14, rationale: '320nm' },
+    { factor: 'classFit',    label: 'Class fit',          weight: 12, score: 10, rationale: 'supramax' },
+    { factor: 'cargoType',   label: 'Cargo type',         weight:  8, score:  7, rationale: 'grain' },
+    { factor: 'cranes',      label: 'Cranes',             weight:  8, score:  6, rationale: 'geared' },
+    { factor: 'volume',      label: 'Volume / stowage',   weight:  4, score:  3, rationale: 'ok' },
+    { factor: 'draft',       label: 'Draft',              weight:  3, score:  2, rationale: 'fits' },
+  ],
+  totalWeight: 100,
+  fitPercent: 82,
+  partCargo: false,
+  vesselClass: 'supramax',
+  sanctionsPenalty: 0,
+  appliedCap: null,
+  inputs: {
+    distanceNm: 320,
+    gapDays: 3,
+    verdict: 'ideal',
+    utilisation: 0.88,
+    vesselDwt: 57000,
+    cargoWtMax: 50000,
+  },
+};
+
+const HARD_FILTERS: MatchHardFilters = {
+  draft: { pass: true },
+  crane: { pass: true },
+  volume: { pass: true },
+  cargoVessel: { pass: true },
+  destDraft: { pass: true },
+  destCrane: { pass: true },
+  cargoWeight: { pass: true },
+};
+
+describe('write-paths-parity (B.2) — computeAndPersistMatches vs persistSessionMatches', () => {
+  const now = new Date();
+  const demoCargo = resolveSyntheticCargo(now);
+  const demoVessel = resolveSyntheticVessel(now);
+
+  // Use the actual cargo laycan so the fail-closed rebuild in persistSessionMatches
+  // does not fire (storedLaycanStart === freshLaycanStart).
+  const parsedLaycan = parseLaycan(demoCargo.laycan)!;
+  const laycanStartIso = parsedLaycan.start.toISOString().slice(0, 10);
+  const laycanEndIso   = parsedLaycan.end.toISOString().slice(0, 10);
+
+  const worksheet: MatchWorksheet = {
+    readiness: {
+      verdict: 'ideal',
+      explanation: 'on-window',
+      openPosition: null,
+      openDate: new Date(now.getTime() + 3 * 86_400_000).toISOString().slice(0, 10),
+      laycanStart: laycanStartIso,
+      laycanEnd:   laycanEndIso,
+      distanceNm: 320,
+      distanceExact: true,
+      speedKn: 13,
+      sailingDays: 1,
+      arrivalDate: new Date(now.getTime() + 4 * 86_400_000).toISOString().slice(0, 10),
+      gapDays: 8,
+    },
+    vessel: {
+      dwtSummer: 58000,
+      draftMax: 12.5,
+      grainCapacity: null,
+      grainCapacityUnit: null,
